def button(label,href,cls='primary'):
 return f'<a class="button {cls}" href="{href}">{label}</a>'

def cards():
 return '<div class="services-grid">'+''.join(f'<a class="service-card" href="/services/{s[0]}/"><span class="service-number">0{i+1}</span><div><h3>{s[1]}</h3><p>{s[3]}</p><span class="small-link">Explore service</span></div></a>' for i,s in enumerate(SERVICES))+'<div class="service-card full-clean"><span class="eyebrow">A complete refresh</span><h3>More than one job?</h3><p>Tell us what needs attention. We’ll discuss a full exterior clean.</p>'+button('Get a tailored quote','/quote/','light')+'</div></div>'

