def save(path,title,desc,body,schema=None):
 file=OUT/path.strip('/')/'index.html' if path!='/' else OUT/'index.html'
 file.parent.mkdir(parents=True,exist_ok=True);file.write_text(shell(title,desc,body,path,schema).replace('href="/', 'href="/dolmen-property-solutions/').replace('src="/', 'src="/dolmen-property-solutions/'));routes[path]=title

